
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_12_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_12", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.037211735423816e+00, -4.937622416945048e+00, -4.797970366629160e+00, -4.604276624060362e+00, -4.339757584706265e+00, -3.986194566899734e+00, -3.527008384600986e+00, -2.951611430176858e+00, -2.260447699295514e+00, -1.501063896154850e+00, -8.843199525349236e-01, -6.371295473740968e-01, -6.269207065492837e-01, -5.353129720074820e-01, -3.631674993913435e-01, -1.970984660170666e-01, -8.579948838757777e-02, -2.834330940294165e-02, -6.080871092153092e-03, -6.841248596858935e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


